// Turns Notion "Monthly Customers" rows into the round each washer sees in the app.
// Kept in one place so the n8n node and the tests run the exact same code.

// Notion's Service Level names, as the app's PLAN keys.
const PLANS = {
  'legacy ₹500': 'legacy',
  'wd standard': 'std',
  'wd pro': 'pro',
  'wd exclusive': 'exc',
  'wd reserve': 'res',
};

// Only these washers have a round in the app. Anything else, including
// "Unassigned", is left out rather than guessed at.
const WASHERS = { chotte: 'chotte', shahrukh: 'shahrukh' };

// A car with no body type drawn for it gets a silhouette; 'suv' is the app's own
// fallback, and these are the words that actually appear in the book.
const SHAPES = [
  [/innova|hycross|carrens|carens|ertiga/i, 'mpv'],
  [/swift|baleno|i20|altroz|punch|ignis|jazz|clubman/i, 'hatch'],
  [/city|slavia|rapid|verna|tigor|camry|530|amaze|taisor/i, 'sedan'],
];
function shapeOf(name) {
  for (const [re, t] of SHAPES) if (re.test(name)) return t;
  return 'suv';
}

const txt = p => ((p && (p.rich_text || p.title)) || []).map(t => t.plain_text).join('').trim();
const pick = p => (p && p.select && p.select.name) || '';
const num = p => (p && typeof p.number === 'number' ? p.number : null);

// One Notion page -> one car on a round, or null if it does not belong on one.
function carOf(page) {
  const p = page.properties || {};
  if (pick(p['Account Status']) !== 'Active') return null;
  const washer = WASHERS[pick(p['Washer']).toLowerCase()];
  if (!washer) return null;

  const name = txt(p['Car']), plate = txt(p['Car Number']);
  // A row still waiting for its registration cannot be matched to a wash, so it
  // would silently never sync. Better the washer sees it is missing.
  const reg = plate.toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!reg || /NUMBERNEEDED/.test(reg)) return null;

  return {
    washer,
    order: typeof (p['Round Order'] || {}).number === 'number' ? p['Round Order'].number : 9999,
    car: {
      plate, reg, make: '', model: name || 'Gaadi', label: name || 'Gaadi',
      plan: PLANS[pick(p['Service Level']).toLowerCase()] || 'std',
      type: shapeOf(name),
      color: '#8a8f98',
      house: txt(p['Area']) || '',
      spot: '',
      customer: 'Customer',
      // what this car pays us a month, so the washer's share can be worked out on his phone
      fee: num(p['Monthly Fee']),
    },
  };
}

// Round Order first where it is set, then area so a washer walks one street at a
// time, then the car's name so the list never reshuffles between loads.
function roundsOf(pages) {
  const out = { chotte: [], shahrukh: [] };
  (pages || []).map(carOf).filter(Boolean)
    .sort((a, b) => a.order - b.order ||
      a.car.house.localeCompare(b.car.house) ||
      a.car.model.localeCompare(b.car.model))
    .forEach(r => out[r.washer].push(r.car));
  return out;
}

// P6: washer is required; the 'all rounds' mode is removed to prevent bulk data exposure.
const res = $input.first().json;
const asked = String(($('Round maango (webhook)').first().json.query || {}).washer || '').toLowerCase();
if (!WASHERS[asked]) {
  return [{ json: { ok: false, error: 'washer parameter is required' } }];
}
const rounds = roundsOf(res.results);

// 100 rows is one Notion page. If the book ever outgrows that, say so in the
// answer rather than quietly handing the washer a short round.
const truncated = !!res.has_more;
return [{ json: { ok: Array.isArray(res.results), washer: asked, cars: rounds[asked] || [], truncated } }];
